// Writes src/styles/vendor-theme.css from the token values in
// src/composables/vendorThemeCore.js, so the CSS and the tested values match.
// Run after changing a token: node scripts/build-vendor-theme-css.mjs
import fs from "node:fs";
import { DARK_TOKENS, LIGHT_TOKENS } from "../src/composables/vendorThemeCore.js";

const block = (tokens) =>
  Object.entries(tokens)
    .map(([name, value]) => `  --v-${name}: ${value};`)
    .join("\n");

const css = `/*
 * Vendor color tokens. GENERATED by scripts/build-vendor-theme-css.mjs from
 * src/composables/vendorThemeCore.js — edit the values there, not here.
 *
 * Light values are the colors the vendor pages always used, so pages and
 * shared components look the same everywhere. Dark values apply only while
 * <html data-vendor-theme="dark">, which useVendorTheme sets on vendor pages.
 */
:root {
${block(LIGHT_TOKENS)}
}

html[data-vendor-theme="dark"] {
${block(DARK_TOKENS)}
  color-scheme: dark;

  /* Toast messages */
  --toastify-color-light: ${DARK_TOKENS.raised};
  --toastify-text-color-light: ${DARK_TOKENS.text};
}

html[data-vendor-theme="dark"] body {
  background: ${DARK_TOKENS.bg};
  color: ${DARK_TOKENS.text};
}

html[data-vendor-theme="dark"] .bc-skeleton {
  background: linear-gradient(100deg, ${DARK_TOKENS["subtle-2"]} 30%, ${DARK_TOKENS.border} 50%, ${DARK_TOKENS["subtle-2"]} 70%);
  background-size: 300% 100%;
}

/* Placeholders: the browser's default grey (and the faint token) is too dim on dark fields */
html[data-vendor-theme="dark"] ::placeholder {
  color: ${DARK_TOKENS.muted} !important;
  opacity: 1;
}

/* Photos and the 3D view keep their own colors; soften glare a little */
html[data-vendor-theme="dark"] img:not([src$=".svg"]) {
  filter: brightness(0.94);
}
`;

const out = new URL("../src/styles/vendor-theme.css", import.meta.url);
fs.writeFileSync(out, css);
console.log(`wrote ${out.pathname}`);
